#include <string>
using namespace std;

class Cat {
public:
    string name;
    int fish;

    Cat(string n, int f) : name(n), fish(f) {}

    void show() const {
        cout << name << " 有 " << fish << " 条" << endl;
    }

    void eat() {
        fish = fish + 1;
        cout << name << " 吃掉了一条" << endl;
    }
};

